25	function dist2d(ax: number, ay: number, bx: number, by: number): number {
26	  return Math.hypot(ax - bx, ay - by);
27	}
28	
29	function buildScatterPositions(
30	  totalCards: number,
31	  spreadX: number,
32	  spreadY: number,
33	): WorksScatterPosition[] {
34	  const cols = Math.ceil(Math.sqrt(totalCards * (spreadX / spreadY)));
35	  const rows = Math.ceil(totalCards / cols);
36	  const stepX = spreadX / Math.max(1, cols);
37	  const stepY = spreadY / Math.max(1, rows);
38	  const out: WorksScatterPosition[] = [];
39	  for (let row = 0; row < rows && out.length < totalCards; row += 1) {
40	    const rowOffset = (row % 2) * (stepX * 0.25);
41	    for (let col = 0; col < cols && out.length < totalCards; col += 1) {
42	      const x = (col - (cols - 1) / 2) * stepX + rowOffset;
43	      const y = (row - (rows - 1) / 2) * stepY;
44	      out.push({ x, y });
45	    }
46	  }
47	  return out;
48	}
49	
50	function sortScatterPositionsFromCenter(
51	  positions: ReadonlyArray<WorksScatterPosition>,
52	): WorksScatterPosition[] {
53	  return [...positions].sort((left, right) => {
54	    const distanceDelta =
55	      Math.hypot(left.x, left.y) - Math.hypot(right.x, right.y);
56	    if (distanceDelta !== 0) {
57	      return distanceDelta;
58	    }
59	    if (left.y !== right.y) {
60	      return left.y - right.y;
61	    }
62	    return left.x - right.x;
63	  });
64	}
