74	class WorksHoverVideoRuntime {
75	  private readonly _video: HTMLVideoElement;
76	  private _texture: THREE.CanvasTexture | null = null;
77	  private _proj: WorkProjectItem | null = null;
78	  private _size: WorkCardSize | null = null;
79	  private _staticImage: HTMLImageElement | null = null;
80	  private _alpha = 0;
81	  private _alphaTarget = 0;
82	
83	  constructor() {
84	    const video = document.createElement("video");
85	    video.muted = true;
86	    video.loop = true;
87	    video.playsInline = true;
88	    video.preload = "auto";
89	    this._video = video;
90	  }
91	
92	  isActive(): boolean {
93	    return this._texture !== null;
94	  }
95	
96	  activate(
97	    mesh: THREE.Mesh,
98	    texture: THREE.CanvasTexture,
99	    videoUrl: string,
100	    proj: WorkProjectItem,
101	    size: WorkCardSize,
102	    staticImage: HTMLImageElement | null,
103	  ): void {
104	    this._texture = texture;
105	    this._proj = proj;
106	    this._size = size;
107	    this._staticImage = staticImage ?? null;
108	    this._alpha = 0;
109	    this._alphaTarget = 1;
110	    if (this._video.src !== videoUrl) {
111	      this._video.src = videoUrl;
112	      this._video.load();
113	    }
114	    void this._video.play().catch(() => undefined);
115	  }
116	
117	  deactivate(): void {
118	    this._video.pause();
119	    this._alphaTarget = 0;
120	  }
121	
122	  drawFrame(): void {
123	    if (!this._texture || !this._proj || !this._size) return;
124	
125	    this._alpha += (this._alphaTarget - this._alpha) * 0.12;
126	
127	    if (this._alphaTarget === 0 && this._alpha < 0.01) {
128	      WorkCard.updateTextureImage(
129	        this._texture,
130	        this._proj,
131	        this._size,
132	        this._staticImage ?? new Image(),
133	        SCATTER_CARD_RENDER_OPTIONS,
134	      );
135	      this._texture = null;
136	      this._proj = null;
137	      this._size = null;
138	      this._staticImage = null;
139	      this._alpha = 0;
140	      return;
141	    }
142	
143	    if (this._alpha > 0.99 && this._alphaTarget === 1) {
144	      WorkCard.updateTextureVideoFrame(
145	        this._texture,
146	        this._proj,
147	        this._size,
148	        this._video,
149	        SCATTER_CARD_RENDER_OPTIONS,
150	      );
151	      return;
152	    }
153	
154	    WorkCard.updateTextureImage(
155	      this._texture,
156	      this._proj,
157	      this._size,
158	      this._staticImage ?? new Image(),
159	      SCATTER_CARD_RENDER_OPTIONS,
160	    );
161	    WorkCard.overlayVideoFrame(this._texture, this._size, this._video, this._alpha);
162	  }
163	
164	  dispose(): void {
165	    this._video.pause();
166	    this._video.src = "";
167	    this._texture = null;
168	    this._proj = null;
169	    this._size = null;
170	    this._staticImage = null;
171	  }
172	}
