364	  private readCameraPlaybackRange(sheetId: WorksTheatreSheetId): WorksTheatrePlaybackRange {
365	    const length = this._lengthBySheetId.get(sheetId) ?? 0;
366	    const configuredRange = this._cameraPlaybackRangeBySheetId.get(sheetId);
367	    if (!configuredRange) {
368	      return {
369	        start: 0,
370	        end: Number.isFinite(length) && length > 0 ? length : 0,
371	      };
372	    }
373	    return {
374	      start: this._clampPosition(configuredRange.start, length),
375	      end: this._clampPosition(configuredRange.end, length),
376	    };
377	  }
