379	  private _readSheetState(
380	    sheetId: WorksTheatreSheetId,
381	    position: number,
382	  ): WorksTheatreSnapshot {
383	    const sequence = this._sequenceBySheetId.get(sheetId);
384	    const object = this._objectBySheetId.get(sheetId);
385	    if (!sequence || !object) return createDefaultWorksTheatreValue();
386	    const previousPosition = sequence.position;
387	    sequence.position = this._clampPosition(
388	      position,
389	      this._lengthBySheetId.get(sheetId) ?? 0,
390	    );
391	    const state = normalizeWorksTheatreValue(object.value);
392	    sequence.position = previousPosition;
393	    return state;
394	  }
