396	  private _resolveSheetLength(
397	    sheetId: WorksTheatreSheetId,
398	    sequence: TheatreSequencePort,
399	  ): number {
400	    const directLength = typeof sequence.length === "number" ? sequence.length : null;
401	    if (directLength != null && Number.isFinite(directLength) && directLength > 0) {
402	      return directLength;
403	    }
404	    return this._readSheetLengthFromState(sheetId);
405	  }
406	
407	  private _readSheetLengthFromState(sheetId: WorksTheatreSheetId): number {
408	    if (!this._stateSource) return 0;
409	    const sheetsById = readRecord(this._stateSource.sheetsById);
410	    if (!sheetsById) return 0;
411	    const sheetState = readRecord(sheetsById[sheetId]);
412	    if (!sheetState) return 0;
413	    const sequence = readRecord(sheetState.sequence);
414	    if (!sequence) return 0;
415	    const length = sequence.length;
416	    if (typeof length !== "number" || !Number.isFinite(length) || length <= 0) {
417	      return 0;
418	    }
419	    return length;
420	  }
421	
422	  private _resolveCameraPreviewRange(
423	    sheetId: WorksTheatreSheetId,
424	    sheetLength: number,
425	  ): WorksTheatrePlaybackRange | null {
426	    const tracksByObject = this._readSheetTracksByObject(sheetId);
427	    const objectTracks = tracksByObject?.[WORKS_THEATRE_OBJECT_ID];
428	    if (!objectTracks || typeof objectTracks !== "object") return null;
429	    const trackData = (objectTracks as Record<string, unknown>).trackData;
430	    if (!trackData || typeof trackData !== "object") return null;
431	    let minPosition = Number.POSITIVE_INFINITY;
432	    let maxPosition = Number.NEGATIVE_INFINITY;
433	    Object.values(trackData as Record<string, unknown>).forEach((trackState) => {
434	      if (!trackState || typeof trackState !== "object") return;
435	      const debugName = (trackState as Record<string, unknown>).__debugName;
436	      if (
437	        typeof debugName !== "string" ||
438	        !WORKS_INTRO_TRACK_DEBUG_NAMES.some((path) => debugName.includes(path))
439	      ) {
440	        return;
441	      }
442	      const keyframes = (trackState as Record<string, unknown>).keyframes;
443	      if (!Array.isArray(keyframes)) return;
444	      const positions = keyframes
445	        .map((keyframe) => {
446	          if (!keyframe || typeof keyframe !== "object") return null;
447	          const keyframePosition = (keyframe as Record<string, unknown>).position;
448	          return typeof keyframePosition === "number" ? keyframePosition : null;
449	        })
450	        .filter(
451	          (keyframePosition): keyframePosition is number =>
452	            typeof keyframePosition === "number" && Number.isFinite(keyframePosition),
453	        );
454	      if (positions.length < 2) return;
455	      minPosition = Math.min(minPosition, ...positions);
456	      maxPosition = Math.max(maxPosition, ...positions);
457	    });
458	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition)) return null;
459	    if (maxPosition <= minPosition) return null;
460	    return {
461	      start: this._clampPosition(minPosition, sheetLength),
462	      end: this._clampPosition(maxPosition, sheetLength),
463	    };
464	  }
465	
466	  private _readSheetTracksByObject(
467	    sheetId: WorksTheatreSheetId,
468	  ): Record<string, unknown> | null {
469	    if (!this._stateSource) return null;
470	    const sheetsById = readRecord(this._stateSource.sheetsById);
471	    if (!sheetsById) return null;
472	    const sheetState = readRecord(sheetsById[sheetId]);
473	    if (!sheetState) return null;
474	    const sequence = readRecord(sheetState.sequence);
475	    if (!sequence) return null;
476	    return readRecord(sequence.tracksByObject);
477	  }
478	
479	  private _clampPosition(position: number, length: number): number {
480	    if (!Number.isFinite(length) || length <= 0) return 0;
481	    if (!Number.isFinite(position)) return 0;
482	    if (position <= 0) return 0;
483	    if (position >= length) return length;
484	    return position;
485	  }
486	}
