170	    this._followCameraEntries = [];
171	    this._groups = { ground: null };
172	    super.dispose();
173	  }
174	
175	  private _disposeLights(): void {
176	    this._lights.forEach((light) => {
177	      light.parent?.remove(light);
178	      const disposable = light as THREE.Light & { dispose?: () => void };
179	      disposable.dispose?.();
180	      const withTarget = light as THREE.Light & { target?: THREE.Object3D };
181	      if (withTarget.target && withTarget.target.parent) {
182	        withTarget.target.parent.remove(withTarget.target);
183	      }
184	    });
185	    this._lights.clear();
186	  }
187	
188	  setState(state: SceneLightsStateSnapshot): void {
189	    if (state.visible) {
190	      this.setVisibleOn();
191	    } else {
192	      this.setVisibleOff();
193	    }
194	    this._setFlightProgress(state.flightProgress);
195	    this._setMasterIntensity(state.intensity);
196	    this._timelineProxy.ground.position = { ...state.ground.position };
197	    this._timelineProxy.ground.rotation = { ...state.ground.rotation };
198	    this._timelineProxy.ground.scale = { ...state.ground.scale };
199	    if (this._groups.ground) {
200	      this._groups.ground.visible = state.ground.visible;
201	    }
202	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
203	    proxy.groundLight = state.groundLight;
204	    proxy.rocketFillLight = state.rocketFillLight;
205	    proxy.rocketRimLightLeft = state.rocketRimLightLeft;
206	    proxy.rocketRimLightRight = state.rocketRimLightRight;
207	    proxy.flightProgress = state.flightProgress;
208	    proxy.intensity = state.intensity;
209	    this._applyGroupTransformsFromProxy();
210	    this._applyScalarStateFromProxy();
211	    this._applyDirectLightIntensityOverrides();
212	    this._syncProxyLightIntensities();
213	    this._syncProxyScalarState();
214	  }
215	
216	  getState(): SceneLightsStateSnapshot {
217	    this._syncProxyFromGroups();
218	    this._syncProxyLightIntensities();
219	    this._syncProxyScalarState();
220	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
221	    return {
222	      visible: this.getVisibleState(),
223	      intensity: this._masterIntensity,
224	      flightProgress: this._flightProgress,
225	      groundLight: this._readNumber(proxy.groundLight, 0),
226	      rocketFillLight: this._readNumber(proxy.rocketFillLight, 0),
227	      rocketRimLightLeft: this._readNumber(proxy.rocketRimLightLeft, 0),
228	      rocketRimLightRight: this._readNumber(proxy.rocketRimLightRight, 0),
229	      ground: this._readGroupTransformState(this._groups.ground),
230	    };
231	  }
