233	  private _rebuildFromSpecs(): void {
234	    const root = this.getTimelineRoot();
235	    if (!root) return;
236	
237	    this._disposeLights();
238	    for (let i = root.children.length - 1; i >= 0; i -= 1) {
239	      root.remove(root.children[i]);
240	    }
241	    this._followCameraEntries = [];
242	    this._groups = { ground: null };
243	
244	    this._createGroupNodes(root);
245	    this._specs.forEach((spec) => this._addLight(spec));
246	    this._buildFollowCameraEntries();
247	    this._syncProxyFromGroups();
248	  }
249	
250	  private _createGroupNodes(root: THREE.Group): void {
251	    const make = (name: string): THREE.Group => {
252	      const g = new THREE.Group();
253	      g.name = name;
254	      root.add(g);
255	      return g;
256	    };
257	    this._groups.ground = make("sceneLights-ground");
258	  }
259	
260	  private _addLight(spec: LightSpec): void {
261	    if (!spec.id) return;
262	    const parent = this._groups.ground;
263	    if (!parent) return;
264	
265	    const color = spec.color ?? 0xffffff;
266	    const intensity = Number.isFinite(spec.intensity as number)
267	      ? Number(spec.intensity)
268	      : 1;
269	    const type = (spec.type ?? "directional").toLowerCase();
270	    const creator = this._creators[type] ?? this._creators.directional;
271	    const light = creator(parent, spec, color, intensity);
272	    light.name = `light:${spec.id}`;
273	    light.layers.set(THREE_LAYER_DEFAULT);
274	    if (spec.affectsEarth !== false) {
275	      light.layers.enable(THREE_LAYER_EARTH);
276	    }
277	    if (spec.affectsRocket) {
278	      light.layers.enable(THREE_LAYER_ROCKET);
279	    }
280	    if (
281	      (light instanceof THREE.DirectionalLight ||
282	        light instanceof THREE.SpotLight) &&
283	      light.target
284	    ) {
285	      light.target.layers.set(THREE_LAYER_DEFAULT);
286	      if (spec.affectsEarth !== false) {
287	        light.target.layers.enable(THREE_LAYER_EARTH);
288	      }
289	      if (spec.affectsRocket) {
290	        light.target.layers.enable(THREE_LAYER_ROCKET);
291	      }
292	    }
293	    parent.add(light);
294	    this._lights.set(spec.id, light);
295	  }
296	
297	  private _applyDirectionalTarget(
298	    parent: THREE.Object3D,
299	    light: THREE.DirectionalLight | THREE.SpotLight,
300	    target?: LightSpec["target"],
301	  ): void {
302	    if (!target) return;
303	    const targetObj = new THREE.Object3D();
304	    targetObj.name = `${light.name || "directionalLight"}:target`;
305	    targetObj.position.set(target.x ?? 0, target.y ?? 0, target.z ?? 0);
306	    parent.add(targetObj);
307	    light.target = targetObj;
308	  }
309	
310	  private _applyShadow(
311	    light: THREE.DirectionalLight | THREE.SpotLight,
312	    spec: LightSpec,
313	  ): void {
314	    if (!spec.castShadow || !light.shadow) return;
315	    light.castShadow = true;
316	    const s = spec.shadow;
317	    if (s?.mapSize) {
318	      light.shadow.mapSize.width = light.shadow.mapSize.height = s.mapSize;
319	    }
320	    if (s?.bias != null) light.shadow.bias = s.bias;
321	    if (s?.normalBias != null) light.shadow.normalBias = s.normalBias;
322	    if (s?.radius != null && "radius" in light.shadow) {
323	      (light.shadow as { radius?: number }).radius = s.radius;
324	    }
325	  }
326	
327	  private _applyPosition(
328	    obj: THREE.Object3D,
329	    pos?: LightSpec["position"],
330	  ): void {
331	    if (!pos) return;
332	    obj.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
333	  }
334	
335	  private _setLights(specs: LightSpec[]): void {
336	    this._specs = specs;
337	  }
338	
339	  private _setFlightProgress(value: number): void {
340	    const clamped = Math.max(
341	      0,
342	      Math.min(1, Number.isFinite(value) ? value : 0),
343	    );
344	    this._flightProgress = clamped;
345	    this._options.flightProgress = clamped;
346	  }
347	
348	  private _setMasterIntensity(value: number): void {
349	    const clamped = Math.max(
350	      0,
351	      Math.min(4, Number.isFinite(value) ? value : 1),
352	    );
353	    this._masterIntensity = clamped;
354	    this._options.intensity = clamped;
355	  }
356	
357	  private _syncProxyFromGroups(): void {
358	    for (const key of ["ground"] as const) {
359	      const g = this._groups[key];
360	      if (!g) continue;
361	      const p = this._timelineProxy[key];
362	      p.position.x = g.position.x;
363	      p.position.y = g.position.y;
364	      p.position.z = g.position.z;
365	      p.rotation.x = Helpers.radToDeg(g.rotation.x);
366	      p.rotation.y = Helpers.radToDeg(g.rotation.y);
367	      p.rotation.z = Helpers.radToDeg(g.rotation.z);
368	      p.scale.x = g.scale.x;
369	      p.scale.y = g.scale.y;
370	      p.scale.z = g.scale.z;
371	    }
372	  }
373	
374	  private _applyGroupTransformsFromProxy(): void {
375	    for (const key of ["ground"] as const) {
376	      const group = this._groups[key];
377	      if (!group) continue;
378	      const src = this._timelineProxy[key];
379	      if (!src?.position || !src?.rotation || !src?.scale) continue;
380	      group.position.set(
381	        src.position.x ?? 0,
382	        src.position.y ?? 0,
383	        src.position.z ?? 0,
384	      );
385	      Helpers.applyRotationDeg(group, src.rotation);
386	      group.scale.set(src.scale.x ?? 1, src.scale.y ?? 1, src.scale.z ?? 1);
387	    }
388	  }
389	
390	  private _applyScalarStateFromProxy(): void {
391	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
392	    const p = proxy.flightProgress;
393	    if (typeof p === "number" && Number.isFinite(p)) {
394	      this._setFlightProgress(p);
395	    }
396	    const intensity = proxy.intensity;
397	    if (typeof intensity === "number" && Number.isFinite(intensity)) {
398	      this._setMasterIntensity(intensity);
399	    }
400	  }
401	
402	  private _applyDirectLightIntensityOverrides(): void {
403	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
404	    for (const [id, light] of this._lights.entries()) {
405	      const base = proxy[id];
406	      if (typeof base !== "number" || !Number.isFinite(base)) continue;
407	      light.intensity = Math.max(0, base) * this._masterIntensity;
408	    }
409	  }
410	
411	  private _syncProxyLightIntensities(): void {
412	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
413	    const master = Math.max(1e-6, this._masterIntensity);
414	    for (const [id, light] of this._lights.entries()) {
415	      proxy[id] = light.intensity / master;
416	    }
417	  }
418	
419	  private _syncProxyScalarState(): void {
420	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
421	    proxy.flightProgress = this._flightProgress;
422	    proxy.intensity = this._masterIntensity;
423	  }
424	
425	  private _buildFollowCameraEntries(): void {
426	    this._followCameraEntries = [];
427	    const camera = this._context?.camera;
428	    if (!(camera instanceof THREE.Object3D)) return;
429	
430	    const camPos = new THREE.Vector3();
431	    const camQuat = new THREE.Quaternion();
432	    const camInvQuat = new THREE.Quaternion();
433	    camera.getWorldPosition(camPos);
434	    camera.getWorldQuaternion(camQuat);
435	    camInvQuat.copy(camQuat).invert();
436	
437	    for (const spec of this._specs) {
438	      const rawFollow = spec.followCamera;
439	      const followOpts =
440	        typeof rawFollow === "object" && rawFollow != null ? rawFollow : null;
441	      const enabled = rawFollow === true || followOpts?.enabled === true;
442	      if (!enabled) continue;
443	
444	      const light = this._lights.get(spec.id);
445	      if (!light) continue;
446	      const rotateWithCamera = followOpts?.rotateWithCamera ?? true;
447	      const lightType = (spec.type ?? "directional").toLowerCase();
448	      const hasTarget = lightType === "directional" || lightType === "spot";
449	      const targetObj =
450	        hasTarget &&
451	        (light instanceof THREE.DirectionalLight ||
452	          light instanceof THREE.SpotLight)
453	          ? light.target
454	          : null;
455	
456	      const positionOffset = followOpts?.positionOffset
457	        ? new THREE.Vector3(
458	            followOpts.positionOffset.x ?? 0,
459	            followOpts.positionOffset.y ?? 0,
460	            followOpts.positionOffset.z ?? 0,
461	          )
462	        : this._worldDeltaToOffset(
463	            light.position.clone().sub(camPos),
464	            rotateWithCamera,
465	            camInvQuat,
466	          );
467	
468	      const targetOffset =
469	        targetObj != null
470	          ? followOpts?.targetOffset
471	            ? new THREE.Vector3(
472	                followOpts.targetOffset.x ?? 0,
473	                followOpts.targetOffset.y ?? 0,
474	                followOpts.targetOffset.z ?? 0,
475	              )
476	            : this._worldDeltaToOffset(
477	                targetObj.position.clone().sub(camPos),
478	                rotateWithCamera,
479	                camInvQuat,
480	              )
481	          : null;
482	
483	      this._followCameraEntries.push({
484	        lightId: spec.id,
485	        rotateWithCamera,
486	        positionOffset,
487	        targetOffset,
488	      });
489	    }
490	  }
491	
492	  private _worldDeltaToOffset(
493	    delta: THREE.Vector3,
494	    rotateWithCamera: boolean,
495	    camInvQuat: THREE.Quaternion,
496	  ): THREE.Vector3 {
497	    if (!rotateWithCamera) return delta;
498	    return delta.applyQuaternion(camInvQuat);
499	  }
500	
501	  private _applyCameraFollow(): void {
502	    if (this._followCameraEntries.length === 0) return;
503	    const camera = this._context?.camera;
504	    if (!(camera instanceof THREE.Object3D)) return;
505	
506	    const camPos = this._followCamPos;
507	    const camQuat = this._followCamQuat;
508	    const worldOffset = this._followWorldOffset;
509	    camera.getWorldPosition(camPos);
510	    camera.getWorldQuaternion(camQuat);
511	
512	    for (const entry of this._followCameraEntries) {
513	      const light = this._lights.get(entry.lightId);
514	      if (!light) continue;
515	
516	      if (entry.positionOffset) {
517	        const lightParent = light.parent;
518	        worldOffset.copy(entry.positionOffset);
519	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
520	        const nextLightWorldPos = this._followWorldTargetPos
521	          .copy(camPos)
522	          .add(worldOffset);
523	        if (lightParent instanceof THREE.Object3D) {
524	          lightParent.worldToLocal(nextLightWorldPos);
525	        }
526	        light.position.copy(nextLightWorldPos);
527	      }
528	
529	      if (
530	        entry.targetOffset &&
531	        (light instanceof THREE.DirectionalLight ||
532	          light instanceof THREE.SpotLight) &&
533	        light.target
534	      ) {
535	        const targetParent = light.target.parent;
536	        worldOffset.copy(entry.targetOffset);
537	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
538	        const nextTargetWorldPos = this._followWorldTargetPos
539	          .copy(camPos)
540	          .add(worldOffset);
541	        if (targetParent instanceof THREE.Object3D) {
542	          targetParent.worldToLocal(nextTargetWorldPos);
543	        }
544	        light.target.position.copy(nextTargetWorldPos);
545	      }
546	    }
547	  }
